const media = [
  {id:'text',label:'Text',symbol:'T'},
  {id:'image',label:'Image',symbol:'▧'},
  {id:'audio',label:'Audio',symbol:'♫'},
  {id:'video',label:'Video',symbol:'▶'}
];
const jurisdictions = {
  argentina:{name:'Argentina',code:'AR',flag:'🇦🇷',status:'Draft / proposed instruments',date:'2 Mar · 28 Aug 2026',summary:'No nationwide binding AI-content labeling or watermark duty identified. Two bills proposing identification and labeling remain pending.',scope:'Bill 0004-D-2026 Article 9 proposes common technical standards and possible markers, labels, watermarks and/or embedded metadata to identify realistic generative content across text, voice, audio, video and image files. Bill 4362-D-2026 proposes a national identification and labeling regime for AI-generated or modified digital content; it remains under committee review.',media:{text:['Proposed','Bill 0004-D-2026 includes text among file types for which realistic generative content could be identified; no current general text-label duty.'],image:['Proposed','Draft proposals include identifying generated or modified digital content; Bill 0004-D-2026 lists image files and possible labels, watermarks, or metadata.'],audio:['Proposed','Bill 0004-D-2026 lists voice and audio files; its technical approaches remain proposals, not current requirements.'],video:['Proposed','Draft proposals cover video or digital content; no binding video label or provenance obligation identified.']},technical:'No enacted national watermark format, provenance standard, detector, authentic-capture signature, or general platform anti-stripping/display duty identified. Article 9 of Bill 0004-D-2026 proposes possible markers for realistic content. Bill 4362-D-2026 remains a proposal.',sources:[['Bill 0004-D-2026 · official Chamber record','https://www.hcdn.gob.ar/secparl/dsecretaria/s_t_parlamentario/tp.html?numero=001&periodo=144'],['Bill 0004-D-2026 · text, Article 9','https://rest.hcdn.gob.ar/web/tramites-parlamentarios/render/adjunto/69a578608bd48.pdf'],['Bill 4362-D-2026 · official docket','https://www.hcdn.gob.ar/comisiones/permanentes/cpyhacienda/proyecto.html?exp=4362-D-2026']]},

  china:{name:'China',code:'CN',flag:'🇨🇳',status:'In force',date:'1 Sep 2025',summary:'A dual-layer approach: visible disclosure in applicable services, plus hidden identification in file metadata.',scope:'Applies to covered online information service providers under China’s deep-synthesis and generative-AI rules. Visible labels are required for specified services and contexts; generated-content files must carry the prescribed implicit metadata.',media:{text:['Required','Text or symbol at a suitable point in the content, or a prominent notice in the interaction interface.'],image:['Required','A prominent disclosure in an appropriate location. Exported files must retain the required explicit mark.'],audio:['Required','A spoken notice or an audio cue at a suitable point in the content.'],video:['Required','A notice on the opening frame and around playback; it may also appear within or at the end of the video.']},technical:'GB 45438-2025 is a mandatory national standard. It specifies visible-mark placement and presentation, as well as required metadata elements such as the synthetic-content attribute, provider name/code, and content identifier. Digital watermarking is an encouraged implementation option, not the only prescribed method.',sources:[['Measures for Labeling AI-Generated Synthetic Content','https://www.cac.gov.cn/2025-03/14/c_1743654684782215.htm'],['GB 45438-2025 · National Standard Information','https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=F32EA2A561F1886CD8D606513512D547&refer=outter']]},
  korea:{name:'South Korea',code:'KR',flag:'🇰🇷',status:'In force · enforcement grace',date:'22 Jan 2026',summary:'A transparency duty covers generative-AI outputs; realistic synthetic sound, images, or video require clearly recognizable disclosure.',scope:'Article 31 of the AI Basic Act applies to AI business operators offering generative-AI products or services, including providers serving users in Korea. The law is in force; MSIT announced at least a one-year grace period for fact-finding and penalties under the transparency provision.',media:{text:['Required','Providers must indicate that generative-AI outputs were generated by AI. For machine-readable marking, the Enforcement Decree also requires at least one human-facing notice.'],image:['Required','AI-generated results must be marked. If an image is difficult to distinguish from reality, disclosure must be clearly recognizable to users.'],audio:['Required','AI-generated results must be marked. Realistic synthetic audio requires clear disclosure; the decree allows machine-readable marking with at least one spoken/text notice.'],video:['Required','AI-generated results must be marked. Realistic synthetic video requires clear disclosure; ministry guidance emphasizes visible labels for deepfakes.']},technical:'The Enforcement Decree permits human-readable or machine-readable marking; machine-readable marking must be accompanied by at least one notice. MSIT guidance differentiates in-service display from exported/distributed content. It allows UI indicators for some in-service content and calls for clearer labels on realistic/deepfake media. No single watermark format is named.',sources:[['AI Basic Act · Article 31 (Korean law portal)','https://www.law.go.kr/LSW/lsLinkCommonInfo.do?chrClsCd=010202&lsJoLnkSeq=1031810715'],['Enforcement Decree · Article 23 (Korean law portal)','https://www.law.go.kr/lsLinkCommonInfo.do?chrClsCd=010202&lspttninfSeq=198075'],['MSIT Guidelines on Ensuring AI Transparency','https://www.msit.go.kr/eng/bbs/view.do?bbsSeqNo=42&mId=4&nttSeqNo=1215&sCode=eng']]},
  india:{name:'India',code:'IN',flag:'🇮🇳',status:'In force · source status partly unverified',date:'1 Mar 2026',summary:'Intermediary rules require labels and provenance mechanisms for certain realistic synthetic audio-visual information.',scope:'The attached Tier 1 research sheet reports the 2026 amendment to the IT Intermediary Rules in force from 1 March 2026, based on secondary sources. It defines synthetic information as audio, visual, or audio-visual content that appears real and depicts a person or event as indistinguishable from reality. Significant social-media intermediaries must verify user declarations and label confirmed synthetic content.',media:{text:['No general duty identified','The definition covers audio, visual, and audio-visual information; the sheet identifies no general provenance-label duty for ordinary generated text.'],image:['Required in scope','In-scope synthetic images must be prominently labelled and carry permanent metadata or another technical provenance mechanism, where technically feasible, including a unique identifier.'],audio:['Required in scope','In-scope synthetic audio must carry a prominent audio disclosure and permanent metadata or another technical provenance mechanism, where technically feasible.'],video:['Required in scope','In-scope synthetic video must have a prominent visual label and permanent metadata or another technical provenance mechanism, where technically feasible.']},technical:'The amendment requires a visible label and permanent metadata or another appropriate technical provenance mechanism, including a unique identifier, where technically feasible. It does not specify one interoperability format or a public general-purpose detector. Significant social-media intermediaries must use appropriate technical measures to verify declarations and label confirmed synthetic content.',sources:[['IT Rules Amendment, 2026 · Gazette of India','https://www.meity.gov.in/static/uploads/2026/02/f55fe52418b03f58b0669f6a8bc03b6d.pdf'],['Government of India · SGI framework summary','https://www.pib.gov.in/PressReleasePage.aspx?PRID=2245053&lang=1&reg=3']]},
  vietnam:{name:'Vietnam',code:'VN',flag:'🇻🇳',status:'In force · implementing decree unverified',date:'1 Mar 2026',summary:'The AI Law requires machine-readable marking of generated image, audio, and video, plus public notice for misleading synthetic content.',scope:'Article 11 of Law No. 134/2025/QH15 requires providers to notify users when they interact with AI and to machine-readably mark AI-generated audio, images, and video. Deployers must clearly notify the public about AI-generated or edited text, audio, images, or video that may confuse people about the authenticity of events or persons. The law text was verified in the attached research sheet; Decree 142/2026/ND-CP was not.',media:{text:['Limited · context-specific','The law does not require machine-readable marking of generated text. Public notice applies when synthetic text may confuse people about the authenticity of events or persons.'],image:['Required','Providers must machine-readably mark generated images. Deployers must give public notice when synthetic images may confuse people about authenticity.'],audio:['Required','Providers must machine-readably mark generated audio. Deployers must give public notice when synthetic audio may confuse people about authenticity.'],video:['Required','Providers must machine-readably mark generated video. Deployers must give public notice when synthetic video may confuse people about authenticity.']},technical:'Article 11 requires machine-readable marking of AI-generated audio, image, and video, in the manner prescribed by the Government. The implementing Decree 142/2026/ND-CP and any detailed technical format were not verified in the attached sheet. The law itself does not set fine amounts; detailed administrative penalties are delegated to the Government.',sources:[['Law No. 134/2025/QH15 · unofficial English translation','https://apolatlegal.com/wp-content/uploads/2026/08/Law-134-2025-QH15.pdf'],['Law No. 134/2025/QH15 · Vietnamese text','https://static3.luatvietnam.vn/uploaded/vietlawfile/2026/06/02/law_134_2025_qh15_ttx_092658.pdf']]},
  kazakhstan:{name:'Kazakhstan',code:'KZ',flag:'🇰🇿',status:'In force · official text not verified',date:'18 Jan 2026 · date conflict noted',summary:'The attached Tier 1 research sheet reports visible and machine-readable labelling duties for AI-generated or materially modified content.',scope:'Law No. 230-VIII “On Artificial Intelligence” is reported in force. Secondary sources describe duties for AI system owners and operators, rather than individual users. The official Adilet text was not retrieved for verification; the attached sheet notes conflicting effective dates of 16 and 18 January 2026.',media:{text:['Reported requirement','Secondary sources describe visible and machine-readable labelling for AI-generated or materially modified text. The official law text was not verified.'],image:['Reported requirement','Secondary sources describe visible and machine-readable labelling for AI-generated or materially modified images. The official law text was not verified.'],audio:['Reported requirement','Secondary sources describe visible and machine-readable labelling for AI-generated or materially modified audio. The official law text was not verified.'],video:['Reported requirement','Secondary sources describe visible and machine-readable labelling for AI-generated or materially modified video. The official law text was not verified.']},technical:'The attached sheet reports no single prescribed format and describes clear visible marking plus machine-readable marking. These details, the effective date, and enforcement provisions remain unverified against the official statute text. The sheet records 18 January 2026 as the most commonly reported effective date and notes one source giving 16 January.',sources:[['Law No. 230-VIII · official Adilet portal','https://adilet.zan.kz']]},
  eu:{name:'European Union',code:'EU',flag:'🇪🇺',status:'Applicable',date:'2 Aug 2026',summary:'Machine-readable and detectable marking for synthetic text, images, audio, and video; separate disclosure duties apply in specific cases.',scope:'Article 50 of the AI Act applies to providers and deployers of in-scope AI systems. Providers mark synthetic outputs. Deployers disclose deepfakes and certain public-interest text, subject to defined exceptions.',media:{text:['Required','Providers mark synthetic text in machine-readable form. Deployers disclose AI text published to inform the public on matters of public interest unless it has meaningful human review/editorial control.'],image:['Required','Machine-readable and detectable marking. If the output is a deepfake, deployers must also disclose it in a way people can perceive.'],audio:['Required','Machine-readable and detectable marking. Deepfake audio also requires a human-perceivable disclosure.'],video:['Required','Machine-readable and detectable marking. Deepfake video also requires a human-perceivable disclosure.']},technical:'The AI Act sets a technology-neutral outcome: effective, reliable, robust, interoperable and machine-readable marking, taking technical feasibility and content-specific limits into account. The Commission-endorsed Code of Practice is voluntary; it offers a route to demonstrate compliance. Techniques may include metadata, watermarking, cryptographic methods, logging, or fingerprints. A limited transition for some pre-2 Aug 2026 systems runs to 2 Dec 2026.',sources:[['AI Act · Article 50 FAQ','https://digital-strategy.ec.europa.eu/en/faqs/transparency-obligations-under-article-50-ai-act'],['Code of Practice on Transparency of AI-Generated Content','https://digital-strategy.ec.europa.eu/en/policies/code-practice-ai-generated-content'],['Regulation (EU) 2024/1689 · AI Act','https://eur-lex.europa.eu/eli/reg/2024/1689/2026-07-27/eng/pdf']]},
  california:{name:'California, United States',code:'US · CA',flag:'🇺🇸',status:'In force · SB 1000 amendments need text check',date:'2 Aug 2026 · amended 30 Sep 2026',summary:'The United States has no comprehensive federal provenance law in this tracker. California has an in-force state provenance law; other Tier 1 state laws mainly address political advertising.',scope:'California’s AI Transparency Act applies to publicly accessible generative-AI systems in California. The attached sheet says SB 1000 removed the one-million-user threshold and the manifest-disclosure option, and renamed the free AI detection tool as a disclosure verification tool. Those SB 1000 changes have not yet been verified against the chaptered text. Large-platform duties under AB 853 and AB 2713 are scheduled for 2027.',media:{text:['No general duty identified','The California provenance provisions focus on image, audio, and video. Other U.S. state laws in the Tier 1 sheet include context-specific political-ad disclosures.'],image:['Required','Covered providers must embed latent, machine-readable provenance and offer a free verification tool. SB 1000 details are flagged for confirmation against chaptered text.'],audio:['Required','Covered providers must embed latent, machine-readable provenance and offer a free verification tool. SB 1000 details are flagged for confirmation against chaptered text.'],video:['Required','Covered providers must embed latent, machine-readable provenance and offer a free verification tool. SB 1000 details are flagged for confirmation against chaptered text.']},technical:'The California law does not prescribe one named watermark format. The attached sheet describes latent disclosure requirements for image, video, and audio, along with a free verification tool. California platform duties begin in 2027; capture-device duties are scheduled for 2028. The sheet flags several SB 1000 and AB 2713 details as not yet verified against chaptered text.',sources:[['California AI Transparency Act · AB 853','https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202520260AB853'],['SB 1000 · chaptered text reference in source sheet','https://legiscan.com/CA/text/SB1000/id/3447341'],['U.S. federal framework · Tier 2 source sheet','https://www.congress.gov']]} ,
  singapore:{name:'Singapore',code:'SG',flag:'🇸🇬',status:'Non-binding guidance',date:'30 May 2024',summary:'The GenAI governance framework recommends provenance technologies, including watermarking and cryptographic provenance, but does not create a general legal labeling duty.',scope:'The Model AI Governance Framework for Generative AI is voluntary guidance for organizations. It discusses labeling or provenance for generated and modified media, especially image, video, and audio. It does not impose a general statutory duty to label every AI-generated output.',media:{text:['Guidance','The framework notes that text-marking technologies are emerging; no general text-label mandate is established.'],image:['Guidance','Discusses visible or technical marks, watermarking, and provenance for AI-generated or modified images.'],audio:['Guidance','Discusses provenance approaches for synthetic media; no binding audio-marking rule identified.'],video:['Guidance','Discusses provenance approaches for synthetic media; no binding video-marking rule identified.']},technical:'The framework distinguishes digital watermarking from cryptographic provenance records. It discusses C2PA as an open standard direction, while noting interoperability and the risk that provenance can be stripped. No Singapore-specific mandatory watermark or provenance format is prescribed.',sources:[['Model AI Governance Framework for Generative AI','https://aiverifyfoundation.sg/resources/mgf-gen-ai/'],['AI Playbook for Small States · Digital FOSS','https://www.imda.gov.sg/about-imda/international-relations/digital-forum-of-small-states'],['IMDA factsheet · GenAI and Digital FOSS AI Governance Playbook','https://www.imda.gov.sg/resources/press-releases-factsheets-and-speeches/factsheets/2024/gen-ai-and-digital-foss-ai-governance-playbook']]},
  malaysia:{name:'Malaysia',code:'MY',flag:'🇲🇾',status:'Binding platform code + draft content code',date:'1 Jun 2026 · draft 2025',summary:'A binding Risk Mitigation Code requires licensed platforms to label or mark certain AI-generated or manipulated content. A broader AI-label rule remains proposed in the 2025 Content Code consultation.',scope:'The Online Safety Act 2025 Risk Mitigation Code applies to licensed application service and content application service providers. Parliamentary material describes labeling/tagging of AI-generated or manipulated content, including deepfakes and image or voice manipulation. It does not establish a general duty for every creator or every AI output.',media:{text:['No general rule identified','The binding platform code is described in relation to synthetic media, deepfakes, image and voice manipulation. The draft Content Code proposes a broader public-content label.'],image:['Limited requirement','Licensed platforms must label or mark covered AI-generated/manipulated content; draft 2025 Content Code proposes a broader public-facing label.'],audio:['Limited requirement','Official parliamentary material mentions voice manipulation and AI-generated/manipulated content; no mandated audio watermark format identified.'],video:['Limited requirement','The platform code covers deepfakes and AI-generated/manipulated content; no mandated video watermark format identified.']},technical:'The binding code requires platform-level labeling/marking, not a named embedded watermark standard. No official requirement for C2PA, signed camera capture, machine-readable provenance metadata, or cross-platform preservation/display of provenance was identified. The 2025 Content Code review paper is a proposal, not the current registered Code.',sources:[['Online Safety Act 2025 · Act 866','https://lom.agc.gov.my/ilims/upload/portal/akta/outputaktap/2867049_BI/Act%20866-Online%20Safety%20Act%202025.pdf'],['Parliament of Malaysia · Digital Hansard, 30 June 2026','https://hansard.parlimen.gov.my/hansard/dewan-rakyat/2026-06-30?search=undefined'],['RTM · MCMC risk code and penalties (21 July 2026)','https://berita.rtm.gov.my/nasional/senarai-berita-nasional/senarai-artikel/platform-media-sosial-diberi-masa-patuhi-kod-mitigasi-risiko/'],['Content Forum · Content Code 2022 (current registered version)','https://contentforum.my/content-code/'],['Content Code Review 2025 · consultation paper','https://contentforum.my/wp-content/uploads/2025/09/Public-Consultation-Paper-on-Content-Code-Review-2025.pdf'],['AI Malaysia / National AI Office · AI governance FAQ','https://www.ai.gov.my/faq/ai-governance-policy/']]},
  saudi:{name:'Saudi Arabia',code:'SA',flag:'🇸🇦',status:'Non-binding guiding principles',date:'2026',summary:'AI Principles in Media call for disclosure of AI-assisted content, using proportionate notices, watermarks, or metadata labels in media contexts.',scope:'The SDAIA and Ministry of Media principles address the media-content lifecycle. Disclosure is especially relevant where AI use materially affects public perception or high-impact content. This is a national guiding framework, not a verified generally applicable statute with fines.',media:{text:['Guidance','Disclosure of AI use in media content; proportionality depends on content impact and context.'],image:['Guidance','Watermarks or other disclosure methods are identified for AI-generated media content.'],audio:['Guidance','The principles cover media content generally; no modality-specific audio watermark format identified.'],video:['Guidance','Watermarks or other disclosure methods are identified for AI-generated media content.']},technical:'Watermarks, notices, and metadata labels are described as disclosure mechanisms. No unified watermark format, mandatory provenance schema, authenticity signature for capture devices, or cross-platform metadata-preservation rule was identified in the published principles.',sources:[['AI Principles in Media · SDAIA official publication','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/ResearchLibrary/AIPrinciplesMedia.pdf'],['Saudi Press Agency · national guiding framework announcement','https://spa.gov.sa/en/N2719773'],['SDAIA Publications','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/Pages/SDAIAPublications.aspx']]},
  uae:{name:'United Arab Emirates',code:'AE',flag:'🇦🇪',status:'Non-binding classification system',date:'16 Jul 2025',summary:'Dubai Future Foundation’s Human–Machine Collaboration Icons disclose how much AI or other machine contribution shaped an output; this is a voluntary visual classification, not a general legal watermark mandate.',scope:'The system is designed for research, publications, and creative, scientific, academic, or intellectual content. It uses five categories from All Human to All Machine and functional icons for parts of the workflow. The official launch says it is adaptable across formats, including image and video.',media:{text:['Voluntary classification','Icons disclose degrees and functions of human–machine collaboration in research and publications.'],image:['Voluntary classification','Visual icons can disclose machine contribution; this is not an embedded image watermark standard.'],audio:['Not specifically established','The launch describes a flexible system but does not specify audio labeling or an audio watermark requirement.'],video:['Voluntary classification','The official launch says the classification can adapt to video outputs; no embedded watermark requirement identified.']},technical:'The HMC icons are a human-readable classification system. Although a news report uses the term “watermark,” the official material describes visual icons and a licensing framework; it does not establish invisible digital watermarking, cryptographic provenance, or a binding obligation for all content publishers.',sources:[['Dubai Media Office · HMC system launch','https://www.protocol.dubai.ae/en/media-listing/news-events/hamdan-bin-mohammed-approves-launch-of-pioneering-human-machine-collaboration-classification-system/'],['Dubai Future Foundation · Research and Publications Standards','https://www.dubaifuture.ae/wp-content/uploads/2025/02/AI-Human-Classification.pdf'],['DFF HMC Classification User Licence','https://www.dubaifuture.ae/wp-content/uploads/2025/05/DFF-HMC-Licence-v2.pdf']]},
  israel:{name:'Israel',code:'IL',flag:'🇮🇱',status:'In force · temporary election-propaganda duty',date:'16 Jul 2026',summary:'A temporary, binding disclosure duty applies to defined deepfake-like content in election propaganda; it is not a general AI-content labelling law.',scope:'The 2026 Elections for the Twenty-Sixth Knesset Law covers election propaganda containing visual or audio content that could appear originally documented but was digitally created or materially changed. The temporary provision runs through one year after the 26th Knesset election.',media:{text:['No general duty identified','The rule applies to defined visual or audio “deep appearance” content in election propaganda, not ordinary generated text.'],image:['Limited','Covered digitally generated or materially altered visual election propaganda must carry a clear, prominent disclosure that it was not originally documented.'],audio:['Limited','Covered audio election propaganda must carry a clear, prominent disclosure that it was not originally documented.'],video:['Limited','Covered visual election propaganda must carry a clear, prominent disclosure; prescribed text or symbols may be used.']},technical:'This is a human-readable disclosure rule. Knesset materials show text or prescribed symbols for print/video. No embedded digital watermark, machine-readable provenance schema, authentic-capture signature, public detector, or general platform preservation rule is specified.',sources:[['Knesset · Elections for the 26th Knesset Law','https://main.knesset.gov.il/apps/legislation/main/laws/2245276'],['Knesset · guidance on AI-era elections and disclosure','https://main.knesset.gov.il/News/PressReleases/Documents/141026.pdf'],['Knesset · Committee discussion (provided link)','https://main.knesset.gov.il/en/news/pressreleases/pages/press3062026q.aspx']]},
  egypt:{name:'Egypt',code:'EG',flag:'🇪🇬',status:'Non-binding guidance',date:'15 Mar 2026',summary:'Egypt’s official AI Governance Framework Guide describes transparency and AI-content labelling or watermarking for limited-risk examples such as chatbots and deepfakes.',scope:'The National AI Governance Framework Guide, Edition 2.0, classifies chatbots and deepfakes as Tier 3 (limited-risk) and discusses disclosure of machine interaction and AI-generated content labelling or watermarking. This is guide-level guidance, not an enacted general labelling statute.',media:{text:['Guidance','The Guide discusses disclosing interaction with AI systems such as chatbots; it does not create an enacted general text-label law.'],image:['Guidance','AI-generated-content labelling or watermarking is included in the Guide’s transparency approach for deepfake examples; no prescribed image-mark format is identified.'],audio:['Guidance','Deepfakes are included in the Guide’s limited-risk transparency discussion; no audio-specific technical format is prescribed.'],video:['Guidance','Deepfakes are included in the Guide’s limited-risk transparency discussion; no video-specific technical format is prescribed.']},technical:'The Guide specifies no required watermark format, machine-readable provenance schema, C2PA profile, public detector, authentic-capture signature, or platform anti-stripping/display obligation. It anticipates further detailed guidance. Do not read the Guide as a binding statutory duty.',sources:[['Egypt National AI Governance Framework Guide, Edition 2.0 (official PDF)','https://ai.gov.eg/SynchedFiles/ar/Resources/Guide%20to%20Egypt%E2%80%99s%20National%20AI%20Governance%20Framework%2015-3-2026.pdf'],['Middle East AI News · Egypt publishes AI governance framework','https://www.middleeastainews.com/p/egypt-publishes-ai-governance-framework']]},
  peru:{name:'Peru',code:'PE',flag:'🇵🇪',status:'Draft / proposed · status not fully verified',date:'27 Nov 2023 (introduced)',summary:'Project 6524/2023 proposes digital labelling for AI-related digital content. It is not in force; the latest status and detailed duties require confirmation in the official Congress file.',scope:'The user-provided Regulations.AI page describes proposed disclosure when AI is used to create, manipulate, or mediate digital content, including text, visual, audio, and audiovisual content. It flags a possible status update that it could not confirm.',media:{text:['Proposed · verify primary text','The Regulations.AI summary includes text content; exact bill language and current docket status are not verified here.'],image:['Proposed · verify primary text','The summary describes digital labelling for visual content; not an in-force obligation.'],audio:['Proposed · verify primary text','The summary describes digital labelling for audio content; not an in-force obligation.'],video:['Proposed · verify primary text','The summary describes digital labelling for audiovisual content; not an in-force obligation.']},technical:'The summary mentions persistent indicators, machine-readable metadata, and provenance records, but those details need confirmation against the complete bill text. No current detector, camera signature, or enacted anti-stripping/platform display duty is established by this proposed bill.',sources:[['Regulations.AI · Peru Digital Labeling Bill 6524/2023','https://regulations.ai/regulations/RAI-PE-NA-P6DLSXX-2023'],['Peru Congress · official bill docket (6524/2023-CR)','https://wb2server.congreso.gob.pe/spley-portal/#/expediente/2021/6524']]},
  turkiye:{name:'Türkiye',code:'TR',flag:'🇹🇷',status:'Draft / proposed · under committee review',date:'5 Dec 2025 (submitted)',summary:'A proposed amendment would require visible labels for AI-generated content; it remains a draft and has no force of law.',scope:'TBMM Bill No. 2/3404 proposes amending Internet Law No. 5651. The bill would require content providers to identify AI-generated written, audio, and visual content with a visible sign, logo, or written notice. The TBMM Justice Commission list records it under review.',media:{text:['Proposed','The draft proposes a visible notice for AI-generated written content.'],image:['Proposed','The draft proposes a visible notice for AI-generated visual content.'],audio:['Proposed','The draft proposes a visible notice for AI-generated audio content.'],video:['Proposed','The draft proposes a visible notice for AI-generated visual content.']},technical:'The proposal describes a human-readable sign, logo, or written notice. It does not prescribe an embedded watermark, metadata format, interoperability standard, camera signature, or detector. Proposed criminal consequences are not current penalties.',sources:[['TBMM · Justice Commission list, Bill No. 2/3404','https://tbmm.gov.tr/ihtisas-komisyonlari/HavaleEdilenIsListesi?Ad=adalet-komisyonu&EsasTali=00000000-0000-0000-0000-000000000000&Id=f72877d1-b46b-037b-e050-007f01005610&Islem=f23daffa-eb3d-4289-adae-0ba21309580d'],['CMS · Türkiye’s parliament receives draft AI-content labelling bill','https://cms.law/en/tur/legal-updates/turkiye-s-parliament-receives-first-criminal-regulation-on-ai-generated-content']]}
};

const standards = [
  {jurisdiction:'Argentina',instrument:'Bills 0004-D-2026 (Art. 9) and 4362-D-2026',kind:'Draft / proposed instruments',coverage:'Proposed: Text · Image · Audio · Video',approach:'Bill 0004-D-2026 proposes common technical standards and possible invisible markers, labels, watermarks, and/or embedded metadata for realistic content across text, voice, audio, video, and image files. Bill 4362-D-2026 proposes a separate identification and labeling regime for AI-generated or modified digital content.',detection:'No in-force detector, prescribed watermark format, camera signature, or general platform duty identified. Both bills remain proposals.',source:'https://www.hcdn.gob.ar/comisiones/permanentes/cpyhacienda/proyecto.html?exp=4362-D-2026',link:'Argentina Chamber of Deputies'},

  {jurisdiction:'China',instrument:'GB 45438-2025',kind:'Mandatory national standard',coverage:'Text · Image · Audio · Video',approach:'Defines explicit mark presentation and required implicit metadata elements. Digital watermarks are encouraged as an implicit technique; the standard is not limited to a single watermark technology.',detection:'Metadata verification and marking/detection implementation are addressed in related technical guidance. A detector result alone does not establish full compliance.',source:'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=F32EA2A561F1886CD8D606513512D547&refer=outter',link:'GB 45438-2025'},
  {jurisdiction:'South Korea',instrument:'AI Basic Act Article 31 + Enforcement Decree',kind:'Binding law and decree; guidance supports implementation',coverage:'Text · Image · Audio · Video',approach:'Requires generated content to be marked; realistic synthetic sound, images, and video require clearly recognizable disclosure. Decree permits human- or machine-readable marking, with an added notice when machine-readable marking is used.',detection:'No single watermark format or general public detection tool is prescribed. MSIT guidance distinguishes in-service UI notice from exported content and emphasizes clear disclosure for deepfakes.',source:'https://www.msit.go.kr/eng/bbs/view.do?bbsSeqNo=42&mId=4&nttSeqNo=1215&sCode=eng',link:'MSIT transparency guidance'},
  {jurisdiction:'India',instrument:'IT Intermediary Rules Amendment 2026',kind:'Binding intermediary rules',coverage:'Audio-visual content: image · audio · video',approach:'Requires prominent labels and permanent metadata or another technical provenance mechanism, including a unique identifier, where technically feasible. Scope is limited to defined realistic synthetic audio-visual information.',detection:'Significant social-media intermediaries must verify user declarations using appropriate technical measures and label confirmed synthetic content. No single provenance format is named.',source:'https://www.meity.gov.in/static/uploads/2026/02/f55fe52418b03f58b0669f6a8bc03b6d.pdf',link:'India IT Rules Amendment'} ,
  {jurisdiction:'Vietnam',instrument:'AI Law No. 134/2025/QH15, Article 11',kind:'Binding law; implementing decree not verified',coverage:'Image · Audio · Video machine-readable; text disclosure is context-specific',approach:'Providers machine-readably mark generated image, audio and video. Deployers visibly notify the public when synthetic content may confuse people about authenticity. The law does not set a general machine-readable text duty.',detection:'No general-purpose detector or single technical format identified in the source sheet. Decree 142/2026/ND-CP remains unverified.',source:'https://apolatlegal.com/wp-content/uploads/2026/08/Law-134-2025-QH15.pdf',link:'Vietnam AI Law · English translation'},
  {jurisdiction:'Kazakhstan',instrument:'Law No. 230-VIII On Artificial Intelligence',kind:'Reported binding law; official text not verified',coverage:'Text · Image · Audio · Video (reported)',approach:'Secondary sources describe both visible and machine-readable marking of generated or materially modified content; no strict format is reported.',detection:'Official statute text and detailed implementation were not verified. The effective date conflicts between 16 and 18 Jan 2026 in the source sheet.',source:'https://adilet.zan.kz',link:'Official Adilet portal'},
  {jurisdiction:'European Union',instrument:'AI Act Article 50 + Code of Practice',kind:'Binding outcome + voluntary compliance code',coverage:'Text · Image · Audio · Video',approach:'Requires machine-readable, detectable marking that is effective, reliable, robust, and interoperable, while accounting for feasibility and media-specific limits. No single format is prescribed.',detection:'The Code of Practice describes practical marking and detection measures. It is voluntary; the underlying Article 50 obligations are binding.',source:'https://digital-strategy.ec.europa.eu/en/policies/code-practice-ai-generated-content',link:'Commission Code of Practice'},
  {jurisdiction:'United States · California',instrument:'AI Transparency Act (SB 942, amended by AB 853 and SB 1000)',kind:'State statute; amendments partly unverified',coverage:'Primarily Image · Audio · Video',approach:'The source sheet describes latent, machine-readable disclosure for covered providers and notes a free verification tool. It flags SB 1000 changes as not yet checked against chaptered text; the former manifest option is reported removed.',detection:'Providers must offer a free verification tool. Large-platform duties are scheduled for 2027 and capture-device duties for 2028; some details remain unverified in the source sheet.',source:'https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202520260AB853',link:'AB 853 · Chapter 674'},
  {jurisdiction:'Singapore',instrument:'MGF for GenAI + Digital FOSS AI Playbook',kind:'Non-binding instruments',coverage:'Mainly Image · Audio · Video; text technology emerging',approach:'MGF discusses watermarking and cryptographic provenance, with C2PA as an open-standard direction. The Digital FOSS Playbook is a policy-practice anthology, not a content-marking rule.',detection:'No general detector or required watermark format identified. Framework notes interoperability and stripping limitations.',source:'https://aiverifyfoundation.sg/resources/mgf-gen-ai/',link:'MGF for GenAI'},
  {jurisdiction:'Malaysia',instrument:'Online Safety Act 2025 Risk Mitigation Code; Content Code Review 2025',kind:'Binding platform code (effective 1 Jun 2026) + draft proposal',coverage:'Binding code: synthetic media, image/voice manipulation and deepfakes; draft proposes broader public-content labeling',approach:'The binding code requires licensed platforms to label/mark covered AI-generated or manipulated content. It does not prescribe a named embedded watermark or provenance format. The 2025 Content Code consultation proposed a broader label.',detection:'No required detector or general machine-readable provenance mechanism identified. Enforcement of ONSA codes can carry statutory penalties; RTM reports fines up to RM10 million for non-compliance.',source:'https://hansard.parlimen.gov.my/hansard/dewan-rakyat/2026-06-30?search=undefined',link:'Parliamentary record on RMC'},
  {jurisdiction:'Saudi Arabia',instrument:'AI Principles in Media',kind:'Non-binding national guiding principles',coverage:'Media content; principles span the content lifecycle',approach:'Calls for proportionate disclosure of AI-assisted content using notices, watermarks, or metadata labels, particularly where public perception or high-impact content is affected.',detection:'No prescribed watermark format, provenance schema, or general detector identified.',source:'https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/ResearchLibrary/AIPrinciplesMedia.pdf',link:'AI Principles in Media · SDAIA'},
  {jurisdiction:'United Arab Emirates',instrument:'Human–Machine Collaboration classification system',kind:'Non-binding visual classification / licensed icon system',coverage:'Research, publications, creative, scientific, academic and intellectual content; adaptable to image and video',approach:'Five icons show the degree of machine contribution and functional icons show where it occurred. The icons are human-readable disclosure, not a machine-readable watermark or provenance credential.',detection:'No detection tool, embedded digital watermark, or provenance metadata standard identified.',source:'https://www.protocol.dubai.ae/en/media-listing/news-events/hamdan-bin-mohammed-approves-launch-of-pioneering-human-machine-collaboration-classification-system/',link:'Dubai Media Office · HMC system launch'},
  {jurisdiction:'Israel',instrument:'Elections for the Twenty-Sixth Knesset Law (temporary disclosure provision)',kind:'Binding but temporary and election-specific',coverage:'Visual · Audio; election propaganda only',approach:'Requires a clear, prominent human-readable disclosure for covered deepfake-like election propaganda. No digital watermark or machine-readable provenance format is prescribed.',detection:'No public detector or general provenance-verification requirement identified.',source:'https://main.knesset.gov.il/apps/legislation/main/laws/2245276',link:'Knesset law record'},
  {jurisdiction:'Egypt',instrument:'National AI Governance Framework Guide, Edition 2.0',kind:'Official non-binding guide (approved 15 Mar 2026)',coverage:'Chatbots and deepfakes; no modality-specific technical schema',approach:'Describes disclosure of machine interaction and AI-generated-content labelling or watermarking for Tier 3 limited-risk examples. It does not prescribe a required watermark or provenance format and is not an enacted general labeling statute.',detection:'No public detector, signed-capture requirement, or platform anti-stripping/display duty identified in this Guide.',source:'https://ai.gov.eg/SynchedFiles/ar/Resources/Guide%20to%20Egypt%E2%80%99s%20National%20AI%20Governance%20Framework%2015-3-2026.pdf',link:'Egypt AI Governance Framework Guide'},
  {jurisdiction:'Peru',instrument:'Project 6524/2023 · Digital Labeling Bill',kind:'Draft / proposed; status and details need primary verification',coverage:'Proposed: Text · Image · Audio · Video (per secondary summary)',approach:'Regulations.AI describes proposed digital labels for AI involvement in creation/manipulation of digital content and mentions persistent or machine-readable provenance. Verify exact provisions against the full bill text.',detection:'No in-force detector or camera-signature requirement established. The proposal’s summarized audit and sanction mechanics are not verified in primary text.',source:'https://regulations.ai/regulations/RAI-PE-NA-P6DLSXX-2023',link:'Regulations.AI bill summary'},
  {jurisdiction:'Türkiye',instrument:'Draft amendment to Internet Law No. 5651 (Bill No. 2/3404)',kind:'Draft / proposed; under committee review',coverage:'Proposed Text · Image · Audio · Video',approach:'Would require a visible sign, logo, or written notice on AI-generated content. The draft does not specify a watermark or machine-readable provenance standard.',detection:'No current duty; proposed criminal consequences are not in force.',source:'https://tbmm.gov.tr/ihtisas-komisyonlari/HavaleEdilenIsListesi?Ad=adalet-komisyonu&EsasTali=00000000-0000-0000-0000-000000000000&Id=f72877d1-b46b-037b-e050-007f01005610&Islem=f23daffa-eb3d-4289-adae-0ba21309580d',link:'TBMM committee status'}
];

let activeMedia='all';
function renderFilters(){
  const root=document.getElementById('media-filters');
  root.innerHTML='<button class="media-filter active" data-media="all">All media</button>'+media.map(m=>`<button class="media-filter" data-media="${m.id}">${m.label}</button>`).join('');
  root.addEventListener('click',e=>{const btn=e.target.closest('[data-media]');if(!btn)return;activeMedia=btn.dataset.media;root.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===btn));renderMatrix();});
  document.getElementById('reset-filter').addEventListener('click',()=>{activeMedia='all';root.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x.dataset.media==='all'));renderMatrix();});
}
function renderProfile(id){
  const d=jurisdictions[id];if(!d)return;
  document.querySelectorAll('.map-marker').forEach(m=>m.classList.toggle('selected',m.dataset.region===id));
  document.getElementById('detail-panel').innerHTML=`<div class="profile-heading"><h3>${d.name}</h3><span class="profile-code">${d.code}</span></div><p class="profile-date"><span>${d.status}</span><b>${d.date}</b></p><p class="profile-summary">${d.summary}</p><div class="profile-rule"><b>Scope</b><p>${d.scope}</p></div><div class="profile-rule"><b>Technical approach</b><p>${d.technical}</p></div><div class="profile-links"><b>Sources</b>${d.sources.map(s=>`<a href="${s[1]}" target="_blank" rel="noopener">${s[0]} <span>↗</span></a>`).join('')}</div>`;
}
function renderMatrix(){
  const selected=activeMedia==='all'?media:media.filter(m=>m.id===activeMedia);
  const root=document.getElementById('matrix-table');root.style.setProperty('--media-count',selected.length);
  root.innerHTML=`<div class="matrix-row matrix-head"><div>Jurisdiction</div>${selected.map(m=>`<div>${m.label}</div>`).join('')}</div>`+Object.entries(jurisdictions).map(([id,r])=>`<div class="matrix-row"><div class="matrix-jurisdiction"><span>${r.flag}</span><div><b>${r.name}</b><small>${r.status} · ${r.date}</small></div></div>${selected.map(m=>{const [status,detail]=r.media[m.id];const tag=status==='Required'?'req':status==='Limited'?'limited':'none';return `<button class="matrix-cell" data-region="${id}" title="${detail}"><span class="cell-tag ${tag}">${status}</span><p>${detail}</p></button>`}).join('')}</div>`).join('');
  root.querySelectorAll('.matrix-cell').forEach(c=>c.addEventListener('click',()=>{renderProfile(c.dataset.region);document.getElementById('map').scrollIntoView({behavior:'smooth'});}));
}
function renderStandards(){document.getElementById('standards-table').innerHTML=`<div class="standards-row standards-head"><div>Jurisdiction &amp; instrument</div><div>Legal status</div><div>Media</div><div>Technical approach</div><div>Detection</div></div>`+standards.map(s=>`<div class="standards-row"><div class="standard-instrument"><b>${s.jurisdiction}</b><a href="${s.source}" target="_blank" rel="noopener">${s.instrument} <span>↗</span></a></div><div>${s.kind}</div><div>${s.coverage}</div><div>${s.approach}</div><div>${s.detection}</div></div>`).join('');}
function renderSources(){const all=[];Object.values(jurisdictions).forEach(r=>r.sources.forEach(s=>all.push({jurisdiction:r.name,title:s[0],url:s[1]})));document.getElementById('source-list').innerHTML=all.map(s=>`<a class="source-item" href="${s.url}" target="_blank" rel="noopener"><span>${s.jurisdiction}</span><b>${s.title}</b><i>↗</i></a>`).join('');}

