function statusColor(category){if(category==='binding')return '#002676';if(category==='nonbinding')return '#fdb515';if(['limited','mixed','draft','unverified'].includes(category))return 'url(#map-stripe)';return '#fff';}
function adoptionColor(value,metric){if(!Number.isFinite(value))return '#f1f2f3';const min=metric==='q2'?0:-2,max=metric==='q2'?75:8,t=Math.max(0,Math.min(1,(value-min)/(max-min))),a=[253,181,21],b=[0,38,118];return `rgb(${a.map((x,i)=>Math.round(x+(b[i]-x)*t)).join(',')})`;}
function renderFallbackLand(svg){const land=svgNode('g',{class:'fallback-land'});for(const coordinates of fallbackContinents){const ring=coordinates.map(([lon,lat])=>project(lon,lat));land.appendChild(svgNode('path',{d:ring.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ')+' Z'}));}svg.appendChild(land);}
function renderLocatorMarkers(svg,mode,metric,clipId=null){const group=svgNode('g',{class:'locator-markers'});if(clipId)group.setAttribute('clip-path',clipId);const seen=new Set();for(const [country,id] of Object.entries(mapProfiles)){if(seen.has(country))continue;seen.add(country);const point=countryCoordinates[country];if(!point)continue;const [cx,cy]=project(point[0],point[1]),category=lawClass(country),value=(adoptionRows[mapCountryKey(country)]||{})[metric==='q2'?'q2':'change'],fill=mode==='law'?statusColor(category):adoptionColor(value,metric),g=svgNode('g',{class:'atlas-locator','role':'button',tabindex:'0','aria-label':countryTip(country,mode)});g.appendChild(svgNode('circle',{class:'locator-halo',cx,cy,r:8}));g.appendChild(svgNode('circle',{class:'locator-dot',cx,cy,r:4.2,fill}));const title=svgNode('title');title.textContent=countryTip(country,mode);g.appendChild(title);const open=()=>renderProfile(id);g.addEventListener('click',open);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});group.appendChild(g);}svg.appendChild(group);}
function setComparisonWipe(svgId,value){const svg=document.getElementById(svgId);if(!svg)return;const split=Math.max(0,Math.min(1000,value)),law=svg.querySelector('#compare-law-clip rect'),adoption=svg.querySelector('#compare-adoption-clip rect'),divider=svg.querySelector('.compare-divider');if(law)law.setAttribute('width',split);if(adoption){adoption.setAttribute('x',split);adoption.setAttribute('width',1000-split);}if(divider)divider.setAttribute('x1',split),divider.setAttribute('x2',split);}
function animateComparisonWipe(slider,button){if(button.dataset.playing==='true'){button.dataset.playing='false';button.textContent='Play comparison';return;}button.dataset.playing='true';button.textContent='Pause comparison';const start=performance.now(),duration=6000;function frame(now){if(button.dataset.playing!=='true')return;const t=Math.min(1,(now-start)/duration),segment=t*3,local=segment%1,eased=(1-Math.cos(Math.PI*local))/2,value=segment<1?Math.round(500+500*eased):segment<2?Math.round(1000-1000*eased):Math.round(500*eased);slider.value=String(value);setComparisonWipe('map-compare',value);slider.setAttribute('aria-valuetext',`Regulation ${value/10}% of map width; AI adoption on remainder`);if(t<1)requestAnimationFrame(frame);else{button.dataset.playing='false';button.textContent='Play comparison';slider.value='500';setComparisonWipe('map-compare',500);slider.setAttribute('aria-valuetext','Equal split: regulation and AI adoption');}}requestAnimationFrame(frame);}
function drawComparisonWipe(svgId,metric,split){const svg=document.getElementById(svgId);if(!svg)return;svg.replaceChildren();const defs=svgNode('defs'),pattern=svgNode('pattern',{id:'compare-stripe',width:8,height:8,patternUnits:'userSpaceOnUse',patternTransform:'rotate(45)'});pattern.appendChild(svgNode('rect',{width:8,height:8,fill:'#fff'}));pattern.appendChild(svgNode('rect',{width:4,height:8,fill:'#fdb515'}));defs.appendChild(pattern);const lawClip=svgNode('clipPath',{id:'compare-law-clip'});lawClip.appendChild(svgNode('rect',{x:0,y:0,width:split,height:550}));const adoptionClip=svgNode('clipPath',{id:'compare-adoption-clip'});adoptionClip.appendChild(svgNode('rect',{x:split,y:0,width:1000-split,height:550}));defs.append(lawClip,adoptionClip);svg.appendChild(defs);if(!worldFeatures.length){renderFallbackLand(svg);renderLocatorMarkers(svg,'law','q2','url(#compare-law-clip)');renderLocatorMarkers(svg,'adoption',metric,'url(#compare-adoption-clip)');svg.appendChild(svgNode('line',{class:'compare-divider',x1:split,y1:0,x2:split,y2:550}));const note=svgNode('text',{x:500,y:535,'text-anchor':'middle',class:'map-fallback-note'});note.textContent='Simplified locator map · detailed boundaries unavailable';svg.appendChild(note);return;}const base=svgNode('g',{class:'country-shapes'}),law=svgNode('g',{class:'country-shapes compare-law-layer','clip-path':'url(#compare-law-clip)'}),adoption=svgNode('g',{class:'country-shapes compare-adoption-layer','clip-path':'url(#compare-adoption-clip)'});for(const feature of worldFeatures){const name=feature.properties.name||feature.properties.ADMIN||feature.properties.NAME||'',id=mapProfiles[name],item=adoptionRows[mapCountryKey(name)],d=geometryPath(feature.geometry),neutral=svgNode('path',{d,class:'country compare-neutral',fill:'#f4f4f1'}),lawPath=svgNode('path',{d,class:`country ${lawClass(name)}`,fill:statusColor(lawClass(name)).replace('map-stripe','compare-stripe')}),adoptionPath=svgNode('path',{d,class:'country adoption-country',fill:adoptionColor(item?.[metric==='q2'?'q2':'change'],metric)});if(id){for(const path of [lawPath,adoptionPath]){path.setAttribute('role','button');path.setAttribute('tabindex','0');path.setAttribute('aria-label',countryTip(name,path===lawPath?'law':'adoption'));path.addEventListener('click',()=>renderProfile(id));path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();renderProfile(id);}});}}const title=svgNode('title');title.textContent=`${countryTip(name,'law')} ${countryTip(name,'adoption')}`;neutral.appendChild(title);base.appendChild(neutral);law.appendChild(lawPath);adoption.appendChild(adoptionPath);}svg.append(base,law,adoption);svg.appendChild(svgNode('line',{class:'compare-divider',x1:split,y1:0,x2:split,y2:550}));}
function drawCountryMap(svgId,mode,metric){const svg=document.getElementById(svgId);svg.replaceChildren();const defs=svgNode('defs'),pattern=svgNode('pattern',{id:'map-stripe',width:8,height:8,patternUnits:'userSpaceOnUse',patternTransform:'rotate(45)'});pattern.appendChild(svgNode('rect',{width:8,height:8,fill:'#fff'}));pattern.appendChild(svgNode('rect',{width:4,height:8,fill:'#fdb515'}));defs.appendChild(pattern);svg.appendChild(defs);if(!worldFeatures.length)renderFallbackLand(svg);else{const countries=svgNode('g',{class:'country-shapes'});for(const feature of worldFeatures){const name=feature.properties.name||feature.properties.ADMIN||feature.properties.NAME||'',profile=mapProfiles[name],item=adoptionRows[mapCountryKey(name)],fill=mode==='law'?statusColor(lawClass(name)):adoptionColor(item?.[metric==='q2'?'q2':'change'],metric),path=svgNode('path',{d:geometryPath(feature.geometry),class:`country ${mode==='law'?lawClass(name):'adoption-country'}`,fill});if(profile){path.setAttribute('role','button');path.setAttribute('tabindex','0');path.setAttribute('aria-label',countryTip(name,mode));path.addEventListener('click',()=>renderProfile(profile));path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();renderProfile(profile);}});}const title=svgNode('title');title.textContent=countryTip(name,mode);path.appendChild(title);countries.appendChild(path);}svg.appendChild(countries);}if(!worldFeatures.length){renderLocatorMarkers(svg,mode,metric);const note=svgNode('text',{x:500,y:535,'text-anchor':'middle',class:'map-fallback-note'});note.textContent='Simplified locator map · detailed boundaries unavailable';svg.appendChild(note);}}
async function loadWorldFeatures(){const failures=[];for(const url of worldUrls){try{const response=await fetch(url);if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();if(data.type==='FeatureCollection'&&Array.isArray(data.features))return data.features.map(feature=>({...feature,properties:{...feature.properties,name:feature.properties.name||feature.properties.ADMIN||feature.properties.NAME}}));throw new Error('Unsupported map data format');}catch(error){failures.push(`${url}: ${error.message}`);}}throw new Error(failures.join(' | '));}
async function loadAtlas(){const adoptionTask=(async()=>{try{const response=await fetch(adoptionUrl);if(!response.ok)throw new Error(`HTTP ${response.status}`);parseAdoption(parseCsv(await response.text()));}catch(error){console.warn('AI adoption dataset unavailable; using embedded fallback values.',error);Object.entries(adoptionFallback).forEach(([n,v])=>adoptionRows[n]={...v,change:+(v.q2-v.q1).toFixed(1)});}})();try{worldFeatures=await loadWorldFeatures();}catch(error){console.warn('World boundaries unavailable; showing the built-in locator map.',error);}await adoptionTask;renderAtlas();}
document.querySelectorAll('.map-tab').forEach(b=>b.addEventListener('click',()=>{mapView=b.dataset.mapView;renderAtlas();}));
